else if(type==='dojo'){ball=mesh(new THREE.CapsuleGeometry(.055,.85,4,8),mat(0x60432f),-1.6,1.6,1.4);ball.rotation.z=.55;scene.add(ball)}scene.add(mesh(new THREE.SphereGeometry(1.05,16,12),new THREE.MeshBasicMaterial({color:0xffe6a3}),-9,11,-18))}
const list=document.querySelector('#sportsList');
SPORTS.forEach((s,i)=>{const card=document.createElement('button');card.className='sport-card'+(!i?' active':'');card.dataset.id=s.id;card.innerHTML=`<span class="sport-icon" style="background:linear-gradient(145deg,${s.colors[0]},${s.colors[1]})">${s.icon}</span><span class="sport-meta"><strong>${s.name}</strong><small>${s.tip}</small></span><span class="sport-tag">${s.tag}</span>`;card.addEventListener('click',()=>selectSport(s));list.append(card)});
const actionBtn=document.querySelector('#actionBtn'),msg=document.querySelector('#gameMsg'),scoreEl=document.querySelector('#score'),needle=document.querySelector('#needle'),toast=document.querySelector('#toast');
function selectSport(s){if(s===current)return;current=s;score=0;playing=false;busy=false;actionCount=0;scoreEl.textContent='00';document.querySelectorAll('.sport-card').forEach(el=>el.classList.toggle('active',el.dataset.id===s.id));document.querySelector('#sceneTitle').textContent=s.name;document.querySelector('#sceneSubtitle').textContent=s.sub;msg.textContent='Pronto para jogar? Acerte no tempo certo!';actionBtn.innerHTML='COMEÇAR JOGO&nbsp; →';buildArena()}
function startGame(){playing=true;score=0;actionCount=0;scoreEl.textContent='00';msg.textContent='Acerte quando o marcador passar pela zona verde!';actionBtn.textContent='BATER AGORA!';if(sound)beep(540,.07)}
function beep(freq=520,dur=.08){if(!sound)return;try{const ac=beep.ac||(beep.ac=new(window.AudioContext||window.webkitAudioContext)());const o=ac.createOscillator(),g=ac.createGain();o.frequency.value=freq;o.type='sine';g.gain.value=.045;o.connect(g);g.connect(ac.destination);o.start();g.gain.exponentialRampToValueAtTime(.001,ac.currentTime+dur);o.stop(ac.currentTime+dur)}catch(e){}}
function showToast(title,sub){document.querySelector('#toastBig').textContent=title;document.querySelector('#toastSmall').textContent=sub;toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),850)}
let flight=null;
function act(){if(!playing){startGame();return}if(busy)return;busy=true;actionCount++;const x=parseFloat(needle.style.left)||0;const good=x>42&&x<58;const sportType=current.type;let title=good?'PERFEITO!':'QUASE!';let details=good?current.tip:'Tente outra vez — mire na zona verde.';if(good){score+=sportType==='bowling'?2:1;scoreEl.textContent=String(score).padStart(2,'0');beep(850,.13)}else beep(230,.12);showToast(title,details);msg.textContent=good?'Boa! Continue assim.':'Ajuste o tempo e tente de novo.';
if(player){player.rotation.y=good?-.24:.15;player.position.x=good?-1.35:-2.45;setTimeout(()=>{if(player){player.rotation.y=0;player.position.x=-2.2}},430)}
if(ball){let target;if(sportType==='bowling')target={x:0,y:.48,z:-8.5};else if(sportType==='golf')target={x:4,y:.16,z:-3};else if(sportType==='field')target={x:good?(Math.random()*1.7-.85):(Math.random()*3-1.5),y:good?1.5:.65,z:-5};else if(sportType==='dojo')target={x:1.55,y:1.6,z:-1.4};else target={x:good?1.5:2.8,y:good?2.2:1.1,z:-2.5};flight={object:ball,from:ball.position.clone(),to:new THREE.Vector3(target.x,target.y,target.z),start:performance.now(),duration:good?780:540,good};}
if(sportType==='bowling'&&good){animObjects.forEach((pin,i)=>setTimeout(()=>{pin.rotation.z=(i%2?.9:-.9);pin.position.y=.35},380+i*45))}
setTimeout(()=>{busy=false;if(ball){ball.position.set(sportType==='bowling'?0:sportType==='golf'?-1:sportType==='field'?-0.8:sportType==='dojo'?-1.6:-1.2,sportType==='bowling'?.48:sportType==='golf'?.18:sportType==='field'?.3:sportType==='dojo'?1.6:1.5,sportType==='bowling'?5:sportType==='golf'||sportType==='field'?1.4:sportType==='dojo'?1.4:-1)}if(sportType==='bowling'&&animObjects.some(p=>Math.abs(p.rotation.z)>.1)){animObjects.forEach(p=>{p.rotation.z=0;p.position.y=.65})}},good?950:700)}
actionBtn.addEventListener('click',act);window.addEventListener('keydown',e=>{if(e.code==='Space'||e.code==='Enter'){e.preventDefault();act()}});document.querySelector('#soundBtn').addEventListener('click',()=>{sound=!sound;document.querySelector('#soundBtn').textContent=sound?'♫':'♪';document.querySelector('#soundBtn').style.opacity=sound?1:.45});
function resize(){const w=stage.clientWidth,h=stage.clientHeight;if(!w||!h)return;renderer.setSize(w,h,false);camera.aspect=w/h;camera.updateProjectionMatrix()}
function animate(){requestAnimationFrame(animate);const t=clock.getElapsedTime();const pos=(Math.sin(t*2.7)+1)*50;needle.style.left=pos+'%';if(ball&&['court','indoor','beach'].includes(current.type)&&!flight)ball.position.y=1.5+Math.sin(t*2.2)*.12;if(player){player.children[1].position.y=2.1+Math.sin(t*2)*.015}if(flight){const p=Math.min(1,(performance.now()-flight.start)/flight.duration),eased=1-Math.pow(1-p,3);flight.object.position.lerpVectors(flight.from,flight.to,eased);flight.object.position.y+=Math.sin(Math.PI*p)*(flight.good?1.6:.55);if(p>=1)flight=null}if(rival)rival.position.x=2+Math.sin(t*.7)*.12;renderer.render(scene,camera)}
setup3d();new ResizeObserver(resize).observe(stage);resize();
</script>
</body>
</html>

